// Test helper; compile only in GitHub Actions. Historical parser/workload kept for comparability.
package main
import("encoding/binary";"fmt";"net";"strings";"strconv";"os";"flag")
func main(){listen:=flag.String("addr","127.0.0.1:15531","isolated fixture bind endpoint");flag.Parse();a,e:=net.ResolveUDPAddr("udp",*listen);if e!=nil{panic(e)};c,e:=net.ListenUDP("udp",a);if e!=nil{panic(e)};defer c.Close();fmt.Println("fixture ready");for{b:=make([]byte,4096);n,peer,e:=c.ReadFromUDP(b);if e!=nil{panic(e)};if n<17{continue};p:=12;labels:=[]string{};for p<n&&b[p]!=0{l:=int(b[p]);p++;if l>63||p+l>n{p=n;break};labels=append(labels,string(b[p:p+l]));p+=l};p++;if p+4>n{continue};typ:=binary.BigEndian.Uint16(b[p:p+2]);end:=p+4;name:=strings.Join(labels,".");ttl:=uint32(30);if strings.HasPrefix(name,"ttl1"){ttl=1};id:=uint32(42);if strings.HasPrefix(name,"q"){v,_:=strconv.Atoi(strings.TrimPrefix(labels[0],"q"));id=uint32(v+1)};if strings.HasPrefix(name,"other"){id=99};var ip []byte;if typ==1{ip=[]byte{198,18,byte(id>>8),byte(id)}}else if typ==28{ip=make([]byte,16);ip[0]=0xfd;ip[1]=0xaa;binary.BigEndian.PutUint32(ip[12:],id)};r:=append([]byte(nil),b[:end]...);binary.BigEndian.PutUint16(r[2:],0x8180);binary.BigEndian.PutUint16(r[6:],0);binary.BigEndian.PutUint16(r[8:],0);binary.BigEndian.PutUint16(r[10:],0);if ip!=nil{binary.BigEndian.PutUint16(r[6:],1);rr:=make([]byte,12);rr[0]=0xc0;rr[1]=12;binary.BigEndian.PutUint16(rr[2:],typ);binary.BigEndian.PutUint16(rr[4:],1);binary.BigEndian.PutUint32(rr[6:],ttl);binary.BigEndian.PutUint16(rr[10:],uint16(len(ip)));r=append(r,rr...);r=append(r,ip...)};if _,e=c.WriteToUDP(r,peer);e!=nil{fmt.Fprintln(os.Stderr,e)}}}
